<script setup lang="ts">
const { t } = useLocale();
const route=useRoute(); const platform=usePlatformApi(); const id=String(route.params.id); const {data:task,pending,error,refresh:reload}=await useAsyncData(`proposal-task-${id}`,()=>platform.getTask(id)); const refresh=()=>reload(); useHead(() => ({ title: t("Предложения команд — Мост") }));</script>
<template><div class="page"><NuxtLink to="/tasks" class="back-link"><AppIcon name="back" :size="15" />{{ t("К моим задачам") }}</NuxtLink><div v-if="pending" class="state-panel" role="status"><span class="state-icon"><AppIcon name="message" /></span><div><strong>{{ t("Загружаем задачу") }}</strong><p>{{ t("Готовим список предложений команд.") }}</p></div></div><div v-else-if="error" class="state-panel state-error" role="alert"><span class="state-icon"><AppIcon name="info" /></span><div><strong>{{ t("Не удалось загрузить задачу") }}</strong><button class="text-link" @click="refresh">{{ t("Попробовать снова") }}</button></div></div><template v-else-if="task"><div class="page-heading"><div><span class="eyebrow"><AppIcon name="message" :size="14" />{{ t("ОТКЛИКИ НА ЗАДАЧУ") }}</span><h1>{{ t("Предложения команд") }}<span class="heading-dot">.</span></h1><p>{{ task.card.title || t("Задача без названия") }}</p></div><span class="badge badge-blue">{{ taskStatusLabel(task.status) }}</span></div><ProposalList :task-id="id" /></template></div></template>
